# -----------------------------------------------------------------
# Function to load the sites with some offset
# -----------------------------------------------------------------
load_sites = function(site_file, Left_offset, Right_offset){
  
  ############ Load the CLIP tags #######################
  
  site_df = read.delim(site_file, header = FALSE)
  colnames(site_df) = c("chr", "pos", "mut")
  site_df$strand = "*"
  
  ############ Remove the NA #####################
  
  site_df = site_df[!is.na(site_df$pos),]
  
  ########### Remove random chromosomes #################
  random_chr_idx = grep("random", site_df$chr)
  
  if (!isEmpty(random_chr_idx)){
    site_df = site_df[-random_chr_idx,]
  }
  
  ######### Creating GRanges object #####################
  
  site_granges <- GRanges(seqnames = site_df[, "chr"],
    IRanges(site_df[, "pos"] - Left_offset, site_df[, "pos"] + Right_offset),
    site_df$strand
  )
  
  return(site_granges)
}

# -----------------------------------------------------------------
# Function to load the regions with some offset
# -----------------------------------------------------------------
load_regions = function(region_file, Left_offset, Right_offset){
  
  ############ Load the regions #######################
  
  region_df = read.delim(region_file, header = TRUE)
  region_df$strand = "*"
  
  ############ Remove the NA #####################
  
  region_df = region_df[!is.na(region_df$start),]
  
  ########### Remove random chromosomes #################
  
  random_chr_idx = grep("random", region_df$chr)
  
  if (!isEmpty(random_chr_idx)){
    region_df = region_df[-random_chr_idx,]
  }
  
  ######### Creating GRanges object #####################
  
  region_granges <- GRanges(
    seqnames = region_df[, "chr"],
    IRanges(region_df[, "start"] - Left_offset, region_df[, "end"] + Right_offset),
    region_df$strand
  )
  
  return(region_granges)
}

# -----------------------------------------------------------------
# Get the number of overlapping sites between the samples
# -----------------------------------------------------------------
find_overlaps = function(
    Mut_sites_paths,
    mut_file,
    type,
    Left_offset,
    Right_offset,
    Transcritome_refs
){
  
  mutation_granges_list = list()
  
  for (sample_idx in 1:length(Mut_sites_paths)) {
    
    mutation_sites_path = Mut_sites_paths[sample_idx]
    
    if (type == "sites") {
      
      mutation_granges = load_sites(site_file = paste0(mutation_sites_path, mut_file), Left_offset, Right_offset)
      
    } else if (type == "regions") {
      
      mutation_granges = load_regions(region_file = paste0(mutation_sites_path, mut_file), Left_offset, Right_offset)
    }
    
    mutation_granges_list[[sample_idx]] = mutation_granges
  }
  
  # Concatenate all GRanges objects into a single GRanges object
  # Get unique regions without merging
  
  all_granges <- unique(do.call(c, mutation_granges_list))
  
  overlap_df = data.frame(ID = 1:length(all_granges))
  
  for (sample_idx in 1:length(mutation_granges_list)) {
    
    overlap_hits <- findOverlaps(all_granges, mutation_granges_list[[sample_idx]])
    
    overlap_present <- 1:length(all_granges) %in% queryHits(overlap_hits)
    
    overlap_df[, Transcritome_refs[sample_idx]] = overlap_present
  }
  
  return(overlap_df)
}

# -----------------------------------------------------------------
# Patching the upset plot
# -----------------------------------------------------------------
patched_upset_plot = function(Mut_sites_paths, type, Left_offset, Right_offset, Transcritome_refs, 
                              Coverage_thresholds, Diff_thresholds, fig_name, fig_sz, sub_plots){
  figure_list = list()
  text_size = 16 
  text_size2 = 6
  
  Diff_thresholds = sort(Diff_thresholds, decreasing = TRUE)
  
  for (diff_idx in 1:length(Diff_thresholds)) {
    
    for (coverage_idx in 1:length(Coverage_thresholds)) {
      
      if (type == "sites") {
        
        mut_file = paste0("cov_thresh_", Coverage_thresholds[coverage_idx], "/Pos_mut_thresh_", Diff_thresholds[diff_idx], ".tsv")
        
      } else if (type == "regions") {
        
        mut_file = paste0("cov_thresh_", Coverage_thresholds[coverage_idx], "/Pos_mut_thresh_", Diff_thresholds[diff_idx], "_region.tsv")
      }
      
      overlap_df = find_overlaps(Mut_sites_paths, mut_file, type, Left_offset, Right_offset, Transcritome_refs)
      
      overlap_df[, -1] <- lapply(overlap_df[, -1], function(x) ifelse(x, 1, 0))
      
      plot_title = paste0("Cov_thresh = ", Coverage_thresholds[coverage_idx], ", Diff_thresh = ", Diff_thresholds[diff_idx])
      
      upset_plot = make_ggupset(overlap_df, plot_title, text_size, text_size2)
      
      figure_list[[length(figure_list) + 1]] = upset_plot
    }
  }
  
  combined_figure = wrap_plots(figure_list, ncol = sub_plots[1], nrow = sub_plots[2], byrow = TRUE)
  
  ggsave(
    fig_name,
    plot = combined_figure,
    width = fig_sz[1] * sub_plots[1],
    height = fig_sz[2] * sub_plots[2],
    limitsize = FALSE,
    device = cairo_pdf
  )
  
}

######### Function to make ggupset plot #####################################

make_ggupset = function(overlap_df, Title, text_size,text_size2){
  
  # Generate list of conditions per row
  condition_list <- apply(overlap_df[, -1], 1, function(x) names(x)[x == 1])
  
  upset_plot_df <- tibble(ID = overlap_df$ID, group = condition_list)
  
  set_order = colnames(overlap_df)[-1]
  
  ################################################
  
  y_lab = "Intersection size"
  x_lab = "group"
  
  upset_plot = ggplot(upset_plot_df,aes(x = group)) +
    
    geom_bar() +
    
    scale_x_upset(sets = set_order) +
    
    geom_text(stat = "count", aes(label = after_stat(count)), vjust = -0.5, size = text_size2) +
    
    labs(
      y = y_lab,
      x = x_lab,
      title = Title
    ) +
    
    theme_minimal(text_size) +
    
    theme(text = element_text(size = text_size),
      
      # Remove grid lines
      panel.grid = element_blank(),
      
      # Add border only on left and bottom
      panel.border = element_blank(),
      
      axis.line = element_line(color = "black", linewidth = 0.8),
      
      axis.text.x = element_text(size = text_size, color = "black", angle = 0, hjust = 1),
      
      axis.title.x = element_text(size = text_size),
      
      axis.text.y = element_text(size = text_size, color = "black"),
      
      axis.title.y = element_text(size = text_size),
      
      plot.title = element_text(size = text_size, hjust = 0.5),
      
      axis.ticks = element_line(color = "black", size = 0.8),
      
      axis.ticks.length = unit(0.25, "cm"),
      
      axis.ticks.x = element_line(color = "black"),
      
      axis.ticks.y = element_line(color = "black")
    )
  
  #########################
  # Set y-axis ticks
  #########################
  
  y_ticks = pretty(c(0, max(table(overlap_df[, -1])) * 1.1), n = 5)
  
  y_min = min(y_ticks)
  y_max = max(y_ticks)
  
  upset_plot =
    upset_plot +
    scale_y_continuous(
      limits = c(y_min, y_max),
      breaks = y_ticks,
      expand = expansion(mult = c(0, 0.02))
    )
  
  return(upset_plot)
}
